// Normalize Instagram comments
const igData = $('Fetch Instagram Comments').first().json;
const igComments = [];

if (igData && igData.data) {
  for (const post of igData.data) {
    if (post.comments && post.comments.data) {
      for (const comment of post.comments.data) {
        igComments.push({
          platform: 'instagram',
          post_id: post.id,
          post_caption: post.caption || '',
          comment_id: comment.id,
          username: comment.username || 'unknown',
          comment_text: comment.text || '',
          timestamp: comment.timestamp || new Date().toISOString(),
          fetched_at: new Date().toISOString()
        });
      }
    }
  }
}

// Normalize Facebook comments
const fbData = $('Fetch Facebook Comments').first().json;
const fbComments = [];

if (fbData && fbData.data) {
  for (const post of fbData.data) {
    if (post.comments && post.comments.data) {
      for (const comment of post.comments.data) {
        fbComments.push({
          platform: 'facebook',
          post_id: post.id,
          post_caption: post.message || '',
          comment_id: comment.id,
          username: (comment.from && comment.from.name) ? comment.from.name : 'unknown',
          comment_text: comment.message || '',
          timestamp: comment.created_time || new Date().toISOString(),
          fetched_at: new Date().toISOString()
        });
      }
    }
  }
}

const allComments = [...igComments, ...fbComments];

if (allComments.length === 0) {
  return [{ json: { _noComments: true, message: 'No comments found in this cycle' } }];
}

return allComments.map(c => ({ json: c }));

// Get list of already-processed comment IDs from Google Sheets
const sheetsData = $('Fetch Processed Comment IDs').first().json;
const processedIds = new Set();

if (sheetsData && sheetsData.values) {
  for (const row of sheetsData.values) {
    if (row[0]) processedIds.add(row[0]);
  }
}

// Filter out already-processed comments
const allItems = $input.all();
const newComments = [];

for (const item of allItems) {
  if (item.json._noComments) continue;
  if (!processedIds.has(item.json.comment_id)) {
    newComments.push(item);
  }
}

if (newComments.length === 0) {
  return [{ json: { _noNewComments: true, message: 'All comments already processed' } }];
}

return newComments;

