// Parse the LLM response and merge with original comment data
const llmResponse = $json;
const originalComment = $('Has New Comments?').item;

let classification = {};

try {
  // The LLM response is in choices[0].message.content
  const content = llmResponse.choices[0].message.content;

  // Try to parse JSON from the response - handle markdown code blocks
  let jsonStr = content;

  // Remove markdown code block wrapping if present
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1].trim();
  }

  classification = JSON.parse(jsonStr);
} catch (e) {
  // Fallback classification if LLM response is malformed
  classification = {
    category: 'IRRELEVANT',
    action: 'LIKE_ONLY',
    priority: 3,
    suggested_reply: 'धन्यवाद! 🙏 हमसे संपर्क करने के लिए शुक्रिया।',
    reasoning: 'LLM parse error - defaulting to safe classification: ' + (e.message || 'unknown error')
  };
}

// Validate classification fields
const validCategories = ['PRODUCT_INQUIRY', 'PRICE_QUESTION', 'COMPLAINT', 'ORDER_QUERY', 'SPAM', 'IRRELEVANT', 'POSITIVE_FEEDBACK', 'COLLABORATION_REQUEST'];
const validActions = ['AUTO_REPLY', 'HIDE', 'DELETE', 'ESCALATE_SALES', 'ESCALATE_SUPPORT', 'ESCALATE_MANAGER', 'LIKE_ONLY'];

if (!validCategories.includes(classification.category)) {
  classification.category = 'IRRELEVANT';
}
if (!validActions.includes(classification.action)) {
  classification.action = 'LIKE_ONLY';
}
if (typeof classification.priority !== 'number' || classification.priority < 1 || classification.priority > 5) {
  classification.priority = 3;
}

return [{
  json: {
    ...originalComment.json,
    category: classification.category,
    action: classification.action,
    priority: classification.priority,
    suggested_reply: classification.suggested_reply || '',
    reasoning: classification.reasoning || '',
    classified_at: new Date().toISOString()
  }
}];

// Hide comment — handles both Instagram and Facebook
const item = $input.item.json;
const token = $env.META_ACCESS_TOKEN;
const commentId = item.comment_id;
const platform = item.platform;

let url, body;

if (platform === 'instagram') {
  // Instagram Graph API: hidden=true
  url = `https://graph.facebook.com/v19.0/${commentId}?hidden=true&access_token=${token}`;
} else {
  // Facebook Graph API: is_hidden=true
  url = `https://graph.facebook.com/v19.0/${commentId}?is_hidden=true&access_token=${token}`;
}

// Make the API call
const resp = await fetch(url, { method: 'POST' });
const result = await resp.json().catch(() => ({}));

return [{
  json: {
    ...item,
    hide_result: result,
    hide_success: result.success || false
  }
}];

