// Like comment — Facebook only (Instagram API does not support this)
const item = $input.item.json;
const platform = item.platform;

if (platform === 'instagram') {
  // Instagram does not allow liking comments via Graph API
  // Just log it — comment is already positive feedback, no action needed
  return [{
    json: {
      ...item,
      like_result: 'skipped',
      like_note: 'Instagram does not support comment likes via API. Comment noted as positive feedback.'
    }
  }];
}

// Facebook — like the comment
const token = $env.META_ACCESS_TOKEN;
const commentId = item.comment_id;
const url = `https://graph.facebook.com/v19.0/${commentId}/likes?access_token=${token}`;
const resp = await fetch(url, { method: 'POST' });
const result = await resp.json().catch(() => ({}));

return [{
  json: {
    ...item,
    like_result: result,
    like_success: result.success || false
  }
}];

// Prepare row data for Google Sheets logging
const item = $input.first().json;

// Try to get the original classified data by traversing back
// This node receives items from ALL switch branches
const now = new Date().toISOString();

const row = {
  timestamp: item.classified_at || item.timestamp || now,
  platform: item.platform || 'unknown',
  post_id: item.post_id || '',
  comment_id: item.comment_id || '',
  username: item.username || '',
  comment_text: item.comment_text || '',
  category: item.category || '',
  action: item.action || '',
  priority: item.priority || 3,
  suggested_reply: item.suggested_reply || '',
  action_taken: 'YES',
  response_time_ms: item.classified_at ? (new Date(now).getTime() - new Date(item.fetched_at).getTime()) : 0,
  logged_at: now
};

return [{ json: row }];
